USE sakila;

SELECT category, COUNT(FID) FROM film_list
GROUP BY category;

SELECT s.store_id, sub.city_name, sub.country_name
FROM (SELECT a.address_id, a.city_id, c.city as city_name, co.country as country_name 
				FROM address a
				LEFT JOIN city c
				ON a.city_id = c.city_id
                LEFT JOIN country co
                ON c.country_id = co.country_id) AS sub, store s 
;

SELECT SUM(total_sales) FROM sales_by_store;

SELECT SUM(amount) FROM payment;

## Calculate the total revenue generated by each store in dollars.
SELECT i.store_id as store_id, SUM(p.amount) as revenue
FROM payment p
LEFT JOIN rental r
ON p.rental_id = r.rental_id
LEFT JOIN inventory i
ON r.inventory_id = i.inventory_id
GROUP BY store_id;

## Determine the average running time of films for each category.
## Identify the film categories with the longest average running time.
SELECT c.name as category, AVG(f.length) as film_duration
FROM film f
LEFT JOIN film_category fc
ON f.film_id = fc.film_id
JOIN category c
ON fc.category_id = c.category_id
GROUP BY category
ORDER BY film_duration DESC;

## Display the top 10 most frequently rented movies in descending order.
SELECT f.title as title, COUNT(rental_id) as nr_of_rental
FROM rental r
LEFT JOIN inventory i 
ON r.inventory_id = i.inventory_id
JOIN film f
ON i.film_id = f.film_id
GROUP BY title
ORDER BY nr_of_rental DESC;


## Determine if "Academy Dinosaur" can be rented from Store 1.
SELECT DISTINCT f.title, i.store_id
FROM inventory i
JOIN film f
ON i.film_id = f.film_id
WHERE f.title = 'Academy Dinosaur' AND i.store_id = 1;

## Provide a list of all distinct film titles, along with their availability status in the inventory. Include a column indicating whether each title is 'Available' or 'NOT available.' 
## Note that there are 42 titles that are not in the inventory, and this information can be obtained using a `CASE` statement combined with `IFNULL`."

SELECT 
    f.title,
    CASE 
        WHEN IFNULL(i.film_id, 0) = 0 THEN 'NOT available'
        ELSE 'Available'
    END AS availability_status
FROM film f
LEFT JOIN inventory i ON f.film_id = i.film_id
GROUP BY f.title, f.film_id
ORDER BY f.title;
